  1052 /* 8.4.5.15 NvDefineIndex() */
  1053 /* This function is used to assign NV memory to an NV Index. */
  1054 /* Error Returns Meaning */
  1055 /* TPM_RC_NV_SPACE insufficient NV space */
  1056 TPM_RC
  1057 NvDefineIndex(
  1058        TPMS_NV_PUBLIC  *publicArea,    // IN: A template for an area to create.
  1059        TPM2B_AUTH      *authValue      // IN: The initial authorization value
  1060        )
  1061 {
  1062
  1063     // The buffer to be written to NV memory
  1064     NV_INDEX        nvIndex;            // the index data
  1065     UINT16          entrySize;          // size of entry
  1066     TPM_RC          result;
  1067     //
  1068     entrySize = sizeof(NV_INDEX);
  1069     // only allocate data space for indexes that are going to be written to NV.
  1070     // Orderly indexes don't need space.
  1071     if(!IS_ATTRIBUTE(publicArea->attributes, TPMA_NV, ORDERLY))
  1072  entrySize += publicArea->dataSize;
  1073     // Check if we have enough space to create the NV Index
  1074     // In this implementation, the only resource limitation is the available NV
  1075     // space (and possibly RAM space.)  Other implementation may have other
  1076     // limitation on counter or on NV slots
  1077     if(!NvTestSpace(entrySize, TRUE, IsNvCounterIndex(publicArea->attributes)))
  1078  return TPM_RC_NV_SPACE;
  1079     // if the index to be defined is RAM backed, check RAM space availability
  1080     // as well
  1081     if(IS_ATTRIBUTE(publicArea->attributes, TPMA_NV, ORDERLY)
  1082        &&  !NvRamTestSpaceIndex(publicArea->dataSize))
  1083  return TPM_RC_NV_SPACE;
  1084     // Copy input value to nvBuffer
  1085     nvIndex.publicArea = *publicArea;
  1086     // Copy the authValue
  1087     nvIndex.authValue = *authValue;
  1088     // Add index to NV memory
  1089     result = NvAdd(entrySize, sizeof(NV_INDEX), TPM_RH_UNASSIGNED,
  1090             (BYTE *)&nvIndex);
  1091     if(result == TPM_RC_SUCCESS)
  1092  {
  1093      // If the data of NV Index is RAM backed, add the data area in RAM as well
  1094      if(IS_ATTRIBUTE(publicArea->attributes, TPMA_NV, ORDERLY))
  1095          NvAddRAM(publicArea);
  1096  }
  1097     return result;
  1098 }
